function SumEvenAtOddIndices(lst: seq<int>): int
{
    var sum := 0;
    var n := |lst|;
    var i := 1;
    while i < n
        invariant 0 <= i <= n
        invariant sum == SumEvenAtOddIndicesHelper(lst, i)
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i];
        }
        i := i + 2;
    }
    return sum;
}

function SumEvenAtOddIndicesHelper(lst: seq<int>, i: int): int
{
    if i == 0 {
        return 0;
    } else if lst[i - 1] % 2 == 0 {
        return SumEvenAtOddIndicesHelper(lst, i - 2) + lst[i - 1];
    } else {
        return SumEvenAtOddIndicesHelper(lst, i - 2);
    }
}
